CREATE OR REPLACE FUNCTION public.phase10_measurements_extended() RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=public AS $$
DECLARE b jsonb; h jsonb; q jsonb; f jsonb;
BEGIN
b:=public.phase10_measurements();
h:=b->'health';
h:=h||jsonb_build_object('canon_drift',public.canon_drift_report(),'orphan_objects',public.graph_orphans(5000));
h:=h||jsonb_build_object('rendition_deletion_evidence',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'ref',r.human_ref,'state',r.state,'stale_at',r.stale_at,'delete_after',r.delete_after,'deleted_at',r.deleted_at,'overdue',r.delete_after<now() AND r.deleted_at IS NULL)) FROM public.renditions r),'[]'));
h:=h||jsonb_build_object('alias_evidence',coalesce((SELECT jsonb_agg(jsonb_build_object('alias',a.alias,'source',a.source_system,'object_id',a.object_id)) FROM public.legacy_aliases a),'[]'));
h:=h||jsonb_build_object('provenance_evidence',coalesce((SELECT jsonb_agg(jsonb_build_object('id',o.id,'ref',o.human_ref,'gap',NOT EXISTS(SELECT 1 FROM public.ledger l WHERE l.provenance_chain_id=o.provenance_chain_id AND l.object_version=o.version))) FROM public.objects o WHERE NOT o.is_tombstone),'[]'));
h:=h||jsonb_build_object('injection_recall_evidence',coalesce((SELECT jsonb_agg(jsonb_build_object('ledger_seq',l.seq,'corpus',l.payload->'injection_corpus','at',l.occurred_at)) FROM public.ledger l WHERE l.action='phase9.exit_evidence'),'[]'));
q:=b->'quality';
q:=q||jsonb_build_object('policy_evidence',coalesce((SELECT jsonb_agg(jsonb_build_object('id',o.id,'ref',o.human_ref,'decision',o.body->'decision','deterministic',o.body->'deterministic','guardrails',o.body->'guardrail_results')) FROM public.objects o WHERE o.type='PolicyEvaluation' AND NOT o.is_tombstone),'[]'));
q:=q||jsonb_build_object('rule_to_test_evidence',coalesce((SELECT jsonb_agg(jsonb_build_object('id',o.id,'ref',o.human_ref,'tests',coalesce((SELECT jsonb_agg(jsonb_build_object('id',t.id,'ref',t.human_ref)) FROM public.edges e JOIN public.objects t ON t.id=e.to_id WHERE e.from_id=o.id AND e.verb='verified_by' AND e.retired_at IS NULL AND NOT t.is_tombstone),'[]'))) FROM public.objects o WHERE o.type IN('Rule','BehaviorStatement') AND NOT o.is_tombstone AND o.lifecycle_state NOT IN('draft','proposed','rejected','superseded')),'[]'));
f:=b->'flow';
f:=f||jsonb_build_object('lifecycle_intervals',coalesce((SELECT jsonb_agg(jsonb_build_object('id',v.id,'ref',v.human_ref,'type',v.type,'state',v.lifecycle_state,'at',v.updated_at,'source','object_versions')) FROM public.object_versions v WHERE v.type IN('ValueSignal','ValueMission','BehaviorStatement','ComposableCapability','WorkingCapability') AND EXISTS(SELECT 1 FROM public.objects o WHERE o.id=v.id AND NOT o.is_tombstone)),'[]'));
f:=f||jsonb_build_object('waiting_evidence',coalesce((SELECT jsonb_agg(jsonb_build_object('id',o.id,'ref',o.human_ref,'hours',public.phase10_elapsed_hours(o.created_at,now()),'deadline',o.body->>'deadline','cost_of_waiting',o.body->>'cost_of_waiting')) FROM public.objects o WHERE o.type='HumanDecisionRequest' AND NOT o.is_tombstone AND NOT o.body ? 'response'),'[]'));
RETURN b||jsonb_build_object('flow',f,'quality',q,'health',h);
END $$;
CREATE OR REPLACE FUNCTION public.thread_record_query_refusal(p_actor jsonb,p_kind text,p_input_hash text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE own uuid; k text; BEGIN PERFORM public._assert_actor(p_actor); PERFORM public._phase10_register(); k:=CASE WHEN p_kind='rejected_measure' THEN 'RejectedMeasureInUse' ELSE 'ProhibitedInference' END; SELECT owner_id INTO own FROM public.detectors WHERE key=k; INSERT INTO public.detector_findings(id,detector_key,severity,owner_id,state,evidence) VALUES(public.uuid_v7(),k,'high',own,'open',jsonb_build_object('owner_id',p_actor->>'id','input_hash',p_input_hash,'explanation','Query refused before execution; request content not retained.')); PERFORM public._mcp_ledger(p_actor,'detector.query.refused',NULL,jsonb_build_object('kind',k,'input_hash',p_input_hash)); END $$;
CREATE INDEX IF NOT EXISTS detection_observations_active ON public.detection_observations(expires_at);
CREATE OR REPLACE FUNCTION public.phase10_schema_check() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('pass',NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND public._rejected_measure(table_name||' '||column_name)) AND NOT EXISTS(SELECT 1 FROM public.objects WHERE type IN('Metric','ValueMeasure') AND NOT is_tombstone AND (public._rejected_measure(title||' '||statement||' '||body::text) OR body->>'counts_drafts'='true')) AND NOT EXISTS(SELECT 1 FROM public.tool_contracts WHERE public._rejected_measure(coalesce((contract->'output_schema')::text,''))),'checked_at',now(),'scope','public fields, measure definitions and tool output contracts') $$;
REVOKE ALL ON FUNCTION public.thread_record_query_refusal(jsonb,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.thread_record_query_refusal(jsonb,text,text) TO service_role;
REVOKE ALL ON FUNCTION public.phase10_measurements_extended() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.phase10_measurements_extended() TO authenticated,service_role;
DO $$ DECLARE t jsonb; BEGIN t:=public.phase10_measurements_extended(); IF jsonb_typeof(t)<>'object' THEN RAISE EXCEPTION 'measurements invalid'; END IF; END $$;